import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] arr = sc.nextLine().split("\\s+");
        String first = arr[0];
        String sec = arr[1];
        int n = Integer.parseInt(sc.nextLine());
        for (int i = n; i > 1; i--) {
            if (n - 4 >= 1) {
                n = n - 4;
            } else {
                break;
            }
        }
        String all = "<^>v";
        int start = 0;
        int end = 0;
        for (int i = 0; i < all.length(); i++) {
            if (first.charAt(0) == all.charAt(i)) {
                start = i;
            }
            if (sec.charAt(0) == all.charAt(i)) {
                end = i;
            }
        }
        if (start == end || start == end - 2 || start == end + 2) {
            System.out.println("undefined");
        } else {
            if (start == end - 1 && n == 1 || start == end + 3 && n == 1 || start == end - 3 && n != 1 || start == end + 1 && n != 1) {
                System.out.println("cw");
            } else if (start == end - 3 && n == 1 || start == end + 1 && n == 1 || start == end - 1 && n != 1 || start == end + 3 && n != 1) {
                System.out.println("ccw");
            }
        }
        sc.close();
    }
}

